sp_widget.client_script:
api.controller = function($scope, $timeout) {

    var c = this;


    /* ============================================================
       INITIAL STATE
       ============================================================ */

    c.search = '';
    c.statusFilter = 'all';
    c.typeFilter = 'all';

    c.filteredOpportunities = [];
    c.selectedOpportunity = null;


    /* ============================================================
       CURRENT TRAINER
       ============================================================ */

    c.getCurrentTrainerId = function() {

        var params =
            new URLSearchParams(
                window.location.search
            );

        return (
            params.get('trainer') ||
            ''
        );

    };


    c.currentTrainerId =
        c.getCurrentTrainerId();


    /* ============================================================
       FILTER OPPORTUNITIES
       ============================================================ */

    c.applyFilters = function() {

        if (
            !c.data ||
            !c.data.opportunities
        ) {

            c.filteredOpportunities = [];

            return;

        }


        var search =
            (c.search || '')
                .toLowerCase()
                .trim();


        c.filteredOpportunities =
            c.data.opportunities.filter(
                function(opportunity) {

                    var matchesSearch =
                        !search ||
                        (
                            (opportunity.title || '')
                                .toLowerCase()
                                .indexOf(search) !== -1
                        ) ||
                        (
                            (opportunity.opportunity_id || '')
                                .toLowerCase()
                                .indexOf(search) !== -1
                        ) ||
                        (
                            (opportunity.company_name || '')
                                .toLowerCase()
                                .indexOf(search) !== -1
                        ) ||
                        (
                            (opportunity.location || '')
                                .toLowerCase()
                                .indexOf(search) !== -1
                        ) ||
                        (
                            (opportunity.required_skills || '')
                                .toLowerCase()
                                .indexOf(search) !== -1
                        );


                    var matchesStatus =
                        c.statusFilter === 'all' ||
                        (
                            (opportunity.status || '')
                                .toLowerCase() ===
                            c.statusFilter.toLowerCase()
                        );


                    var matchesType =
                        c.typeFilter === 'all' ||
                        (
                            (opportunity.opportunity_type || '')
                                .toLowerCase() ===
                            c.typeFilter.toLowerCase()
                        );


                    return (
                        matchesSearch &&
                        matchesStatus &&
                        matchesType
                    );

                }
            );

    };


    /* ============================================================
       SEARCH WATCHERS
       ============================================================ */

    $scope.$watch(
        'c.search',
        function() {

            c.applyFilters();

        }
    );


    $scope.$watch(
        'c.statusFilter',
        function() {

            c.applyFilters();

        }
    );


    $scope.$watch(
        'c.typeFilter',
        function() {

            c.applyFilters();

        }
    );


    /* ============================================================
       CLEAR SEARCH
       ============================================================ */

    c.clearSearch = function() {

        c.search = '';
        c.statusFilter = 'all';
        c.typeFilter = 'all';

        c.applyFilters();

    };


    /* ============================================================
       OPEN OPPORTUNITY
       ============================================================ */

    c.openOpportunity = function(
        opportunity
    ) {

        if (!opportunity) {
            return;
        }


        c.selectedOpportunity =
            opportunity;


        $timeout(
            function() {

                var element =
                    document.querySelector(
                        '.c360-details-panel'
                    );


                if (element) {

                    element.scrollIntoView({
                        behavior: 'smooth',
                        block: 'start'
                    });

                }

            },
            80
        );

    };


    /* ============================================================
       CLOSE OPPORTUNITY
       ============================================================ */

    c.closeOpportunity = function() {

        c.selectedOpportunity = null;

    };


    /* ============================================================
       REFRESH
       ============================================================ */

    c.refresh = function() {

        c.selectedOpportunity = null;

        c.server.update().then(
            function() {

                c.applyFilters();

            }
        );

    };


    /* ============================================================
       ESCAPE KEY
       ============================================================ */

    c.onKeyDown = function(
        event
    ) {

        if (
            event &&
            event.keyCode === 27
        ) {

            if (
                c.selectedOpportunity
            ) {

                c.closeOpportunity();

            }

        }

    };


    /* ============================================================
       CLEANUP
       ============================================================ */

    c.$onDestroy = function() {

        c.selectedOpportunity = null;

    };


    /* ============================================================
       INITIAL FILTER
       ============================================================ */

    $timeout(
        function() {

            c.applyFilters();

        },
        100
    );

};

sp_widget.css:
/* ========================================================= 
   CAMPUS360 TRAINER 
   OPPORTUNITIES & ROOMS 
   DASHBOARD-STYLE SHELL 
   FULL SCREEN 100% PC VIEW 
   DARK PURPLE SIDE NAVBAR - STUDENT PAGE STYLE
   ========================================================= */ 
 
 
/* ========================================================= 
   RESET 
   ========================================================= */ 
 
html, 
body { 
 
  width:100% !important; 
  height:100% !important; 
 
  min-width:100% !important; 
  min-height:100% !important; 
 
  margin:0 !important; 
  padding:0 !important; 
 
} 
 
 
body { 
 
  overflow-x:hidden !important; 
 
  background:#f2f6fa !important; 
 
} 
 
 
/* ========================================================= 
   SERVICENOW CONTAINER RESET 
   ========================================================= */ 
 
.container:has(.campus360-opportunities-app), 
.container-fluid:has(.campus360-opportunities-app), 
.row:has(.campus360-opportunities-app), 
[class*="col-"]:has(.campus360-opportunities-app), 
.well:has(.campus360-opportunities-app), 
.panel:has(.campus360-opportunities-app) { 
 
  width:100% !important; 
 
  max-width:none !important; 
 
  min-width:0 !important; 
 
  margin:0 !important; 
 
  padding:0 !important; 
 
  border:0 !important; 
 
  background:transparent !important; 
 
  box-shadow:none !important; 
 
} 
 
 
/* ========================================================= 
   COMPLETE CAMPUS360 APPLICATION 
   ========================================================= */ 
 
.campus360-opportunities-app { 
 
  position:fixed !important; 
 
  top:0 !important; 
  left:0 !important; 
  right:0 !important; 
  bottom:0 !important; 
 
  width:100vw !important; 
 
  height:100vh !important; 
 
  min-width:100vw !important; 
  min-height:100vh !important; 
 
  max-width:100vw !important; 
  max-height:100vh !important; 
 
  margin:0 !important; 
 
  padding:0 !important; 
 
  z-index:2147483647 !important; 
 
  display:flex !important; 
 
  flex-direction:row !important; 
 
  overflow:hidden !important; 
 
  isolation:isolate; 
 
  background: 
 
    radial-gradient( 
      circle at 8% 8%, 
      rgba(238,230,255,.55), 
      transparent 25% 
    ), 
 
    radial-gradient( 
      circle at 96% 9%, 
      rgba(227,245,255,.58), 
      transparent 26% 
    ), 
 
    linear-gradient( 
      135deg, 
      #f6f8fc 0%, 
      #f3f7fb 52%, 
      #f9f6ff 100% 
    ); 
 
  color:#263a52; 
 
  font-family: 
    "Segoe UI", 
    "Inter", 
    Arial, 
    sans-serif; 
 
  -webkit-font-smoothing:antialiased; 
 
} 
 
 
.campus360-opportunities-app, 
.campus360-opportunities-app *, 
.campus360-opportunities-app *::before, 
.campus360-opportunities-app *::after { 
 
  box-sizing:border-box; 
 
} 
 
 
/* ========================================================= 
   SIDEBAR 
   DARK PURPLE - SAME STYLE AS STUDENT PAGES
   ========================================================= */ 
 
.campus360-opportunities-app 
.campus360-trainer-sidebar { 
 
  position:relative !important; 
 
  top:0 !important; 
  left:0 !important; 
 
  width:280px !important; 
 
  min-width:280px !important; 
 
  max-width:280px !important; 
 
  height:100vh !important; 
 
  min-height:100vh !important; 
 
  max-height:100vh !important; 
 
  flex:0 0 280px !important; 
 
  display:flex; 
 
  flex-direction:column; 
 
  overflow:hidden; 
 
  background: 
    linear-gradient( 
      180deg, 
      #130d2f 0%, 
      #160d38 48%, 
      #100a29 100% 
    ) !important; 
 
  border-right:1px solid #2d2157 !important; 
 
  box-shadow: 
    5px 
    0 
    18px 
    rgba(10,7,30,.18); 
 
  z-index:100; 
 
  transition: 
    width .25s ease, 
    min-width .25s ease, 
    max-width .25s ease, 
    flex-basis .25s ease; 
 
} 
 
 
/* ========================================================= 
   COLLAPSED SIDEBAR 
   ========================================================= */ 
 
.campus360-opportunities-app.sidebar-collapsed 
.campus360-trainer-sidebar { 
 
  width:0 !important; 
 
  min-width:0 !important; 
 
  max-width:0 !important; 
 
  flex-basis:0 !important; 
 
  border-right:0 !important; 
 
} 
 
 
/* ========================================================= 
   BRAND
   DARK PURPLE
   ========================================================= */ 
 
.campus360-opportunities-app 
.trainer-brand { 
 
  width:100%; 
 
  height:98px; 
 
  min-height:98px; 
 
  padding: 
    0 
    17px; 
 
  display:flex; 
 
  align-items:center; 
 
  gap:13px; 
 
  flex-shrink:0; 
 
  background: 
    linear-gradient( 
      135deg, 
      #170e38, 
      #1c1045 
    ) !important; 
 
  border-bottom:1px solid #2d2157 !important; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-brand-mark { 
 
  width:50px; 
 
  height:50px; 
 
  min-width:50px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border-radius:14px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #7c3aed, 
      #8b3ff2 
    ) !important; 
 
  color:#ffffff; 
 
  font-size:23px; 
 
  box-shadow: 
    0 
    8px 
    18px 
    rgba(124,58,237,.28); 
 
} 
 
 
.campus360-opportunities-app 
.trainer-brand-text { 
 
  min-width:0; 
 
  display:flex; 
 
  flex-direction:column; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-brand-text strong { 
 
  display:block; 
 
  color:#ffffff !important; 
 
  font-size:21px; 
 
  line-height:1; 
 
  font-weight:900; 
 
  letter-spacing:-.3px; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-brand-text span { 
 
  display:block; 
 
  margin-top:5px; 
 
  color:#b9abd8 !important; 
 
  font-size:10px; 
 
  line-height:1; 
 
  font-weight:900; 
 
  letter-spacing:1.25px; 
 
} 
 
 
/* ========================================================= 
   TRAINER PROFILE
   DARK PURPLE
   ========================================================= */ 
 
.campus360-opportunities-app 
.trainer-profile-mini { 
 
  margin: 
    18px 
    10px 
    15px; 
 
  min-height:74px; 
 
  padding:11px; 
 
  display:flex; 
 
  align-items:center; 
 
  gap:10px; 
 
  flex-shrink:0; 
 
  background: 
    linear-gradient( 
      135deg, 
      #211342, 
      #29164f 
    ) !important; 
 
  border:1px solid #4b3475 !important; 
 
  border-radius:13px; 
 
  text-decoration:none !important; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-profile-mini:hover { 
 
  background: 
    linear-gradient( 
      135deg, 
      #29174f, 
      #321d5d 
    ) !important; 
 
  border-color:#60458e !important; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-avatar { 
 
  width:46px; 
 
  height:46px; 
 
  min-width:46px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border-radius:12px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #7c3aed, 
      #8b3ff2 
    ) !important; 
 
  color:#ffffff !important; 
 
  font-size:13px; 
 
  font-weight:900; 
 
  box-shadow: 
    0 
    5px 
    14px 
    rgba(124,58,237,.20); 
 
} 
 
 
.campus360-opportunities-app 
.trainer-profile-info { 
 
  flex:1; 
 
  min-width:0; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-profile-info strong { 
 
  display:block; 
 
  overflow:hidden; 
 
  color:#ffffff !important; 
 
  font-size:13px; 
 
  line-height:1.2; 
 
  font-weight:850; 
 
  white-space:nowrap; 
 
  text-overflow:ellipsis; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-profile-info span { 
 
  display:block; 
 
  margin-top:4px; 
 
  color:#b9abd8 !important; 
 
  font-size:9px; 
 
  font-weight:800; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-profile-arrow { 
 
  color:#a99bc7 !important; 
 
  font-size:19px; 
 
} 
 
 
/* ========================================================= 
   SIDEBAR NAVIGATION
   DARK PURPLE - STUDENT PAGE STYLE
   ========================================================= */ 
 
.campus360-opportunities-app 
.trainer-nav { 
 
  flex:1; 
 
  min-height:0; 
 
  overflow-x:hidden; 
 
  overflow-y:auto; 
 
  padding: 
    0 
    6px 
    20px; 
 
  scrollbar-width:none !important; 
 
  -ms-overflow-style:none !important; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav::-webkit-scrollbar { 
 
  width:0 !important; 
 
  height:0 !important; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav::-webkit-scrollbar-track { 
 
  background:transparent !important; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav::-webkit-scrollbar-thumb { 
 
  background:transparent !important; 
 
  border-radius:10px; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav-label { 
 
  margin: 
    18px 
    7px 
    8px; 
 
  color:#9283b6 !important; 
 
  font-size:10px; 
 
  line-height:1; 
 
  font-weight:900; 
 
  letter-spacing:1.15px; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav-item { 
 
  position:relative; 
 
  width:100%; 
 
  min-height:48px; 
 
  margin: 
    2px 
    0; 
 
  padding: 
    0 
    11px; 
 
  display:flex; 
 
  align-items:center; 
 
  gap:11px; 
 
  border-radius:10px; 
 
  color:#c4b8dc !important; 
 
  background:transparent !important; 
 
  text-decoration:none !important; 
 
  font-size:13px; 
 
  line-height:1.25; 
 
  font-weight:850; 
 
  transition: 
    background .18s ease, 
    color .18s ease, 
    transform .18s ease; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav-item:hover { 
 
  color:#ffffff !important; 
 
  background:rgba(124,58,237,.18) !important; 
 
  transform:translateX(1px); 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav-item.active { 
 
  color:#ffffff !important; 
 
  background: 
    linear-gradient( 
      90deg, 
      #7c3aed 0%, 
      #8b3ff2 100% 
    ) !important; 
 
  border-left:4px solid #a78bfa !important; 
 
  padding-left:7px; 
 
  box-shadow: 
    inset 
    0 
    0 
    0 
    1px 
    rgba(196,181,253,.10), 
 
    0 
    6px 
    16px 
    rgba(124,58,237,.18); 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav-icon { 
 
  width:28px; 
 
  min-width:28px; 
 
  height:28px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  color:#a99ac8 !important; 
 
  font-size:18px; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav-item:hover 
.trainer-nav-icon { 
 
  color:#ffffff !important; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav-item.active 
.trainer-nav-icon { 
 
  color:#ffffff !important; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav-count { 
 
  min-width:23px; 
 
  height:23px; 
 
  margin-left:auto; 
 
  padding:0 6px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border-radius:20px; 
 
  background:#3a2764 !important; 
 
  color:#d9ceef !important; 
 
  font-size:9px; 
 
  font-weight:900; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav-item.active 
.trainer-nav-count { 
 
  background:rgba(255,255,255,.18) !important; 
 
  color:#ffffff !important; 
 
} 
 
 
.campus360-opportunities-app 
.trainer-nav-count.warning { 
 
  background:#5a3511 !important; 
 
  color:#ffd08a !important; 
 
} 
 
 
/* ========================================================= 
   MAIN 
   ========================================================= */ 
 
.campus360-trainer-main { 
 
  width: 
    calc(100vw - 280px) !important; 
 
  max-width: 
    calc(100vw - 280px) !important; 
 
  min-width:0 !important; 
 
  height:100vh !important; 
 
  min-height:100vh !important; 
 
  max-height:100vh !important; 
 
  flex:1 1 auto; 
 
  margin:0 !important; 
 
  padding:0 !important; 
 
  overflow-x:hidden !important; 
 
  overflow-y:auto !important; 
 
  background:#f3f6fb; 
 
  transition: 
    width .25s ease, 
    max-width .25s ease; 
 
} 
 
 
/* Collapsed */ 
 
.sidebar-collapsed 
.campus360-trainer-main { 
 
  width:100% !important; 
 
  max-width:100% !important; 
 
} 
 
 
/* ========================================================= 
   TOPBAR 
   WHITE - KEPT UNCHANGED
   ========================================================= */ 
 
.trainer-topbar { 
 
  position:sticky; 
 
  top:0; 
 
  z-index:500; 
 
  width:100%; 
 
  height:72px; 
 
  min-height:72px; 
 
  padding: 
    0 
    19px 
    0 
    22px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:space-between; 
 
  gap:18px; 
 
  background: 
    linear-gradient( 
      90deg, 
      #ffffff, 
      #fbfdff 
    ); 
 
  border-bottom:1px solid #dce4ec; 
 
  box-shadow: 
    0 
    2px 
    10px 
    rgba(23,43,67,.035); 
 
} 
 
 
.trainer-topbar-left { 
 
  min-width:0; 
 
  display:flex; 
 
  align-items:center; 
 
  gap:12px; 
 
} 
 
 
.trainer-hamburger { 
 
  width:44px; 
 
  height:44px; 
 
  min-width:44px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border:1px solid #d6e0e8; 
 
  border-radius:10px; 
 
  background:#ffffff; 
 
  color:#536a81; 
 
  font-size:18px; 
 
  cursor:pointer; 
 
} 
 
 
.trainer-hamburger:hover { 
 
  color:#643fe1; 
 
  background:#f5f1ff; 
 
  border-color:#cec1f4; 
 
} 
 
 
/* ========================================================= 
   TOP HEADING 
   ========================================================= */ 
 
.trainer-page-heading { 
 
  min-width:0; 
 
  display:flex; 
 
  flex-direction:column; 
 
} 
 
 
.trainer-topbar-eyebrow { 
 
  display:block; 
 
  color:#7244e8; 
 
  font-size:9px; 
 
  line-height:1; 
 
  font-weight:950; 
 
  letter-spacing:1.7px; 
 
} 
 
 
.trainer-topbar-title { 
 
  display:block; 
 
  margin-top:4px; 
 
  color:#1a304a; 
 
  font-size:16px; 
 
  line-height:1.1; 
 
  font-weight:900; 
 
} 
 
 
/* ========================================================= 
   TOP RIGHT 
   ========================================================= */ 
 
.trainer-topbar-actions { 
 
  display:flex; 
 
  align-items:center; 
 
  gap:9px; 
 
  flex-shrink:0; 
 
} 
 
 
.trainer-top-icon { 
 
  position:relative; 
 
  width:42px; 
 
  height:42px; 
 
  min-width:42px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border:1px solid #d7e0e8; 
 
  border-radius:10px; 
 
  background:#ffffff; 
 
  color:#5b7187; 
 
  font-size:16px; 
 
  cursor:pointer; 
 
} 
 
 
.trainer-top-icon:hover { 
 
  color:#6843df; 
 
  background:#f5f1ff; 
 
  border-color:#cfc2f6; 
 
} 
 
 
/* ========================================================= 
   NOTIFICATION 
   ========================================================= */ 
 
.trainer-notification-button { 
 
  overflow:visible; 
 
} 
 
 
.trainer-notification-button 
.fa-bell { 
 
  color:#f4a400; 
 
  font-size:17px; 
 
} 
 
 
.trainer-notification-dot { 
 
  position:absolute; 
 
  top:7px; 
 
  right:7px; 
 
  width:8px; 
 
  height:8px; 
 
  border-radius:50%; 
 
  background:#ef4444; 
 
  border:2px solid #ffffff; 
 
} 
 
 
/* ========================================================= 
   TOP TRAINER PROFILE 
   ========================================================= */ 
 
.trainer-top-profile { 
 
  min-height:43px; 
 
  padding-left:11px; 
 
  display:flex; 
 
  align-items:center; 
 
  gap:8px; 
 
  border-left:1px solid #e2e7ed; 
 
  text-decoration:none !important; 
 
} 
 
 
.trainer-top-avatar { 
 
  width:42px; 
 
  height:42px; 
 
  min-width:42px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border-radius:10px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #693ef2, 
      #8053ff 
    ); 
 
  color:#ffffff; 
 
  font-size:10px; 
 
  font-weight:900; 
 
} 
 
 
.trainer-top-profile-text { 
 
  display:flex; 
 
  flex-direction:column; 
 
} 
 
 
.trainer-top-profile-text strong { 
 
  display:block; 
 
  color:#23384f; 
 
  font-size:11px; 
 
  line-height:1.1; 
 
  font-weight:900; 
 
} 
 
 
.trainer-top-profile-text span { 
 
  display:block; 
 
  margin-top:3px; 
 
  color:#7c8a9c; 
 
  font-size:8px; 
 
  line-height:1; 
 
  font-weight:750; 
 
} 
 
 
/* ========================================================= 
   SIDEBAR OVERLAY 
   ========================================================= */ 
 
.trainer-sidebar-overlay { 
 
  display:none; 
 
} 
 
 
/* ========================================================= 
   PAGE CONTENT 
   ========================================================= */ 
 
.trainer-opportunities-content { 
 
  width:100% !important; 
 
  max-width:none !important; 
 
  min-width:0; 
 
  margin:0 !important; 
 
  padding: 
    23px 
    24px 
    40px; 
 
  background: 
 
    radial-gradient( 
      circle at 95% 14%, 
      rgba(230,245,255,.35), 
      transparent 24% 
    ), 
 
    radial-gradient( 
      circle at 3% 58%, 
      rgba(241,232,255,.38), 
      transparent 25% 
    ), 
 
    #f3f6fb; 
 
} 
 
 
/* ========================================================= 
   WELCOME 
   ========================================================= */ 
 
.opportunity-welcome { 
 
  width:100%; 
 
  min-height:157px; 
 
  margin-bottom:17px; 
 
  padding: 
    25px 
    28px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:space-between; 
 
  gap:25px; 
 
  background: 
    linear-gradient( 
      110deg, 
      #ffffff 0%, 
      #f8f4ff 55%, 
      #f1fbf9 100% 
    ); 
 
  border:1px solid #d9d3ed; 
 
  border-radius:16px; 
 
  box-shadow: 
    0 
    5px 
    15px 
    rgba(42,52,75,.045); 
 
} 
 
 
.opportunity-welcome-copy { 
 
  min-width:0; 
 
  flex:1; 
 
} 
 
 
.trainer-eyebrow { 
 
  display:block; 
 
  margin-bottom:7px; 
 
  color:#6842df; 
 
  font-size:9px; 
 
  line-height:1; 
 
  font-weight:950; 
 
  letter-spacing:1.6px; 
 
} 
 
 
.opportunity-welcome h1 { 
 
  margin:0; 
 
  color:#182c48; 
 
  font-size:34px; 
 
  line-height:1.08; 
 
  font-weight:950; 
 
  letter-spacing:-.7px; 
 
} 
 
 
.opportunity-welcome p { 
 
  max-width:970px; 
 
  margin: 
    8px 
    0 
    0; 
 
  color:#617289; 
 
  font-size:13px; 
 
  line-height:1.6; 
 
  font-weight:600; 
 
} 
 
 
.opportunity-trainer-card { 
 
  width:228px; 
 
  min-width:228px; 
 
  min-height:82px; 
 
  padding:12px 14px; 
 
  display:flex; 
 
  align-items:center; 
 
  gap:10px; 
 
  background:#ffffff; 
 
  border:1px solid #ddd3f7; 
 
  border-radius:12px; 
 
  box-shadow: 
    0 
    5px 
    12px 
    rgba(70,55,120,.045); 
 
} 
 
 
.opportunity-trainer-avatar { 
 
  width:45px; 
 
  height:45px; 
 
  min-width:45px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border-radius:11px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #6b3df4, 
      #8054ff 
    ); 
 
  color:#ffffff; 
 
  font-size:11px; 
 
  font-weight:900; 
 
} 
 
 
.opportunity-trainer-card span { 
 
  display:block; 
 
  color:#8391a3; 
 
  font-size:8px; 
 
  line-height:1; 
 
  font-weight:950; 
 
  letter-spacing:1px; 
 
} 
 
 
.opportunity-trainer-card strong { 
 
  display:block; 
 
  margin-top:4px; 
 
  color:#243a51; 
 
  font-size:12px; 
 
  font-weight:900; 
 
} 
 
 
.opportunity-trainer-card small { 
 
  display:block; 
 
  margin-top:3px; 
 
  color:#7b899a; 
 
  font-size:9px; 
 
} 
 
 
/* ========================================================= 
   KPI GRID 
   ========================================================= */ 
 
.opportunity-kpi-grid { 
 
  width:100%; 
 
  display:grid; 
 
  grid-template-columns: 
    repeat( 
      4, 
      minmax(0,1fr) 
    ); 
 
  gap:14px; 
 
  margin-bottom:17px; 
 
} 
 
 
.opportunity-kpi-card { 
 
  min-height:135px; 
 
  padding:18px; 
 
  display:flex; 
 
  align-items:center; 
 
  gap:13px; 
 
  border:1px solid; 
 
  border-radius:14px; 
 
} 
 
 
.kpi-purple { 
 
  background: 
    linear-gradient( 
      135deg, 
      #f0e9ff, 
      #e2d6ff 
    ); 
 
  border-color:#d2c0fa; 
 
} 
 
 
.kpi-teal { 
 
  background: 
    linear-gradient( 
      135deg, 
      #ffeae2, 
      #ffe0d5 
    ); 
 
  border-color:#f1c9bc; 
 
} 
 
 
.kpi-orange { 
 
  background: 
    linear-gradient( 
      135deg, 
      #e9f8f7, 
      #d9f0ee 
    ); 
 
  border-color:#bce2df; 
 
} 
 
 
.kpi-green { 
 
  background: 
    linear-gradient( 
      135deg, 
      #fdebf1, 
      #f8dfe7 
    ); 
 
  border-color:#ecc3d0; 
 
} 
 
 
.opportunity-kpi-icon { 
 
  width:52px; 
 
  height:52px; 
 
  min-width:52px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border-radius:13px; 
 
  background:rgba(255,255,255,.88); 
 
  font-size:19px; 
 
} 
 
 
.kpi-purple 
.opportunity-kpi-icon { 
 
  color:#6441dc; 
 
} 
 
 
.kpi-teal 
.opportunity-kpi-icon { 
 
  color:#b65f47; 
 
} 
 
 
.kpi-orange 
.opportunity-kpi-icon { 
 
  color:#147b7d; 
 
} 
 
 
.kpi-green 
.opportunity-kpi-icon { 
 
  color:#b13e69; 
 
} 
 
 
.opportunity-kpi-content { 
 
  min-width:0; 
 
} 
 
 
.opportunity-kpi-content span { 
 
  display:block; 
 
  color:#6f7d90; 
 
  font-size:8px; 
 
  font-weight:950; 
 
  letter-spacing:1px; 
 
} 
 
 
.opportunity-kpi-content strong { 
 
  display:block; 
 
  margin-top:5px; 
 
  color:#132c48; 
 
  font-size:29px; 
 
  line-height:1; 
 
  font-weight:950; 
 
} 
 
 
.opportunity-kpi-content small { 
 
  display:block; 
 
  margin-top:6px; 
 
  color:#748398; 
 
  font-size:9px; 
 
  font-weight:650; 
 
} 
 
 
/* ========================================================= 
   PANELS 
   ========================================================= */ 
 
.trainer-panel { 
 
  width:100%; 
 
  margin-bottom:17px; 
 
  padding: 
    22px; 
 
  background: 
    rgba(255,255,255,.98); 
 
  border: 
    1px 
    solid 
    #dce4ec; 
 
  border-radius:15px; 
 
  box-shadow: 
    0 
    5px 
    17px 
    rgba(34,48,67,.04); 
 
} 
 
 
.trainer-panel-heading { 
 
  display:flex; 
 
  align-items:flex-start; 
 
  justify-content:space-between; 
 
  gap:15px; 
 
  padding-bottom:16px; 
 
  border-bottom:1px solid #e4e9ef; 
 
} 
 
 
.trainer-panel-heading.compact { 
 
  align-items:center; 
 
} 
 
 
.trainer-panel-heading > div > span { 
 
  display:block; 
 
  margin-bottom:5px; 
 
  color:#6542dc; 
 
  font-size:8px; 
 
  font-weight:950; 
 
  letter-spacing:1.5px; 
 
} 
 
 
.trainer-panel-heading h2 { 
 
  margin:0; 
 
  color:#172d49; 
 
  font-size:22px; 
 
  line-height:1.15; 
 
  font-weight:950; 
 
} 
 
 
.trainer-panel-heading p { 
 
  margin: 
    5px 
    0 
    0; 
 
  color:#718096; 
 
  font-size:10px; 
 
  line-height:1.45; 
 
} 
 
 
/* ========================================================= 
   SEARCH 
   ========================================================= */ 
 
.opportunity-search-grid { 
 
  display:grid; 
 
  grid-template-columns: 
    minmax(0,1fr) 
    180px 
    180px; 
 
  gap:10px; 
 
  margin-top:17px; 
 
} 
 
 
.opportunity-search-box { 
 
  height:49px; 
 
  padding: 
    0 
    13px; 
 
  display:flex; 
 
  align-items:center; 
 
  gap:9px; 
 
  border:1px solid #d7e0e9; 
 
  border-radius:9px; 
 
  background:#fbfcfe; 
 
} 
 
 
.opportunity-search-box:focus-within { 
 
  background:#ffffff; 
 
  border-color:#9984e8; 
 
  box-shadow: 
    0 
    0 
    0 
    3px 
    rgba(101,66,232,.07); 
 
} 
 
 
.opportunity-search-box i { 
 
  color:#159293; 
 
  font-size:14px; 
 
} 
 
 
.opportunity-search-box input { 
 
  width:100%; 
 
  height:100%; 
 
  padding:0; 
 
  border:0; 
 
  outline:0; 
 
  background:transparent; 
 
  color:#30445a; 
 
  font-size:11px; 
 
} 
 
 
.opportunity-search-box input::placeholder { 
 
  color:#9aa7b6; 
 
} 
 
 
.opportunity-filter { 
 
  height:49px; 
 
  padding: 
    0 
    11px; 
 
  border:1px solid #d7e0e9; 
 
  border-radius:9px; 
 
  background:#fbfcfe; 
 
  color:#364b62; 
 
  font-size:10px; 
 
  cursor:pointer; 
 
} 
 
 
.opportunity-filter:focus { 
 
  border-color:#9984e8; 
 
  box-shadow: 
    0 
    0 
    0 
    3px 
    rgba(101,66,232,.07); 
 
} 
 
 
.opportunity-clear-btn { 
 
  height:35px; 
 
  padding: 
    0 
    11px; 
 
  border:1px solid #d9e0e8; 
 
  border-radius:8px; 
 
  background:#ffffff; 
 
  color:#6b7a8c; 
 
  font-size:9px; 
 
  font-weight:800; 
 
  cursor:pointer; 
 
} 
 
 
.opportunity-clear-btn:hover { 
 
  background:#fff0f4; 
 
  color:#b83e67; 
 
  border-color:#edc6d4; 
 
} 
 
 
.opportunity-record-count { 
 
  padding: 
    6px 
    10px; 
 
  background:#e2f4f1; 
 
  color:#197879; 
 
  border:1px solid #bfe4e1; 
 
  border-radius:18px; 
 
  font-size:8px; 
 
  font-weight:900; 
 
} 
 
 
/* ========================================================= 
   OPPORTUNITY LIST 
   ========================================================= */ 
 
.opportunity-list { 
 
  display:flex; 
 
  flex-direction:column; 
 
  gap:13px; 
 
  padding-top:16px; 
 
} 
 
 
.opportunity-card { 
 
  position:relative; 
 
  overflow:hidden; 
 
  padding: 
    18px 
    18px 
    0; 
 
  border: 
    1px 
    solid 
    #dce3eb; 
 
  border-radius:11px; 
 
  background:#ffffff; 
 
  box-shadow: 
    0 
    3px 
    9px 
    rgba(30,44,62,.025); 
 
  transition: 
    transform .18s ease, 
    box-shadow .18s ease, 
    border-color .18s ease; 
 
} 
 
 
.opportunity-card:hover { 
 
  transform:translateY(-2px); 
 
  border-color:#cbbef1; 
 
  box-shadow: 
    0 
    8px 
    19px 
    rgba(46,48,84,.065); 
 
} 
 
 
.opportunity-card-color { 
 
  position:absolute; 
 
  left:0; 
 
  top:0; 
 
  bottom:0; 
 
  width:4px; 
 
  background:#6843de; 
 
} 
 
 
.opportunity-card:nth-child(4n+2) 
.opportunity-card-color { 
 
  background:#199192; 
 
} 
 
 
.opportunity-card:nth-child(4n+3) 
.opportunity-card-color { 
 
  background:#de7d2b; 
 
} 
 
 
.opportunity-card:nth-child(4n+4) 
.opportunity-card-color { 
 
  background:#cf537d; 
 
} 
 
 
/* ========================================================= 
   OPPORTUNITY CARD HEADER 
   ========================================================= */ 
 
.opportunity-card-top { 
 
  display:grid; 
 
  grid-template-columns: 
    auto 
    minmax(0,1fr) 
    auto; 
 
  align-items:center; 
 
  gap:12px; 
 
} 
 
 
.company-avatar { 
 
  width:47px; 
 
  height:47px; 
 
  min-width:47px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border-radius:11px; 
 
  background:#eee7ff; 
 
  color:#6542df; 
 
  font-size:11px; 
 
  font-weight:900; 
 
} 
 
 
.opportunity-card:nth-child(4n+2) 
.company-avatar { 
 
  background:#dff4f2; 
 
  color:#167a7c; 
 
} 
 
 
.opportunity-card:nth-child(4n+3) 
.company-avatar { 
 
  background:#fff0e1; 
 
  color:#bd6a23; 
 
} 
 
 
.opportunity-card:nth-child(4n+4) 
.company-avatar { 
 
  background:#fde8ef; 
 
  color:#b84468; 
 
} 
 
 
.opportunity-main-title { 
 
  min-width:0; 
 
} 
 
 
.opportunity-id { 
 
  display:block; 
 
  color:#6542dc; 
 
  font-size:8px; 
 
  font-weight:950; 
 
  letter-spacing:.9px; 
 
} 
 
 
.opportunity-main-title h3 { 
 
  margin: 
    4px 
    0 
    0; 
 
  color:#20354d; 
 
  font-size:17px; 
 
  line-height:1.25; 
 
  font-weight:900; 
 
} 
 
 
.opportunity-main-title p { 
 
  margin: 
    4px 
    0 
    0; 
 
  color:#718095; 
 
  font-size:10px; 
 
} 
 
 
.opportunity-main-title p i { 
 
  margin-right:3px; 
 
  color:#168d90; 
 
} 
 
 
.opportunity-status { 
 
  display:inline-flex; 
 
  align-items:center; 
 
  gap:5px; 
 
  padding: 
    6px 
    9px; 
 
  border-radius:15px; 
 
  font-size:8px; 
 
  font-weight:900; 
 
} 
 
 
.opportunity-status i { 
 
  font-size:5px; 
 
} 
 
 
.opportunity-status.open { 
 
  background:#e4f6eb; 
 
  color:#22744e; 
 
  border:1px solid #c2e3cf; 
 
} 
 
 
.opportunity-status.closed { 
 
  background:#edf0f3; 
 
  color:#677589; 
 
  border:1px solid #dbe1e6; 
 
} 
 
 
.opportunity-status.hold { 
 
  background:#fff1de; 
 
  color:#a95f10; 
 
  border:1px solid #efd5b4; 
 
} 
 
 
/* ========================================================= 
   DETAILS GRID 
   ========================================================= */ 
 
.opportunity-details-grid { 
 
  display:grid; 
 
  grid-template-columns: 
    repeat( 
      4, 
      minmax(0,1fr) 
    ); 
 
  gap:9px; 
 
  margin-top:15px; 
 
} 
 
 
.opportunity-detail { 
 
  min-height:60px; 
 
  padding: 
    10px 
    11px; 
 
  border:1px solid; 
 
  border-radius:8px; 
 
} 
 
 
.opportunity-detail span { 
 
  display:block; 
 
  margin-bottom:5px; 
 
  font-size:7px; 
 
  font-weight:950; 
 
  letter-spacing:.8px; 
 
} 
 
 
.opportunity-detail strong { 
 
  display:block; 
 
  color:#32465c; 
 
  font-size:10px; 
 
  font-weight:850; 
 
} 
 
 
.opportunity-detail strong i { 
 
  margin-right:4px; 
 
} 
 
 
.detail-purple { 
 
  background:#f8f5ff; 
 
  border-color:#e1d9fa; 
 
} 
 
 
.detail-purple span, 
.detail-purple strong i { 
 
  color:#6541dd; 
 
} 
 
 
.detail-teal { 
 
  background:#f1fbfa; 
 
  border-color:#d1ece9; 
 
} 
 
 
.detail-teal span, 
.detail-teal strong i { 
 
  color:#177b7c; 
 
} 
 
 
.detail-orange { 
 
  background:#fff8ee; 
 
  border-color:#f1dfca; 
 
} 
 
 
.detail-orange span, 
.detail-orange strong i { 
 
  color:#c26c20; 
 
} 
 
 
.detail-pink { 
 
  background:#fff5f8; 
 
  border-color:#f0d9e1; 
 
} 
 
 
.detail-pink span, 
.detail-pink strong i { 
 
  color:#b34469; 
 
} 
 
 
/* ========================================================= 
   SKILLS 
   ========================================================= */ 
 
.opportunity-skills { 
 
  margin-top:13px; 
 
} 
 
 
.opportunity-field-label { 
 
  display:block; 
 
  margin-bottom:6px; 
 
  color:#8592a3; 
 
  font-size:7px; 
 
  font-weight:950; 
 
  letter-spacing:1px; 
 
} 
 
 
.skill-tags { 
 
  display:flex; 
 
  flex-wrap:wrap; 
 
  gap:5px; 
 
} 
 
 
.skill-tag { 
 
  padding: 
    5px 
    8px; 
 
  border-radius:6px; 
 
  background:#eee8ff; 
 
  border:1px solid #dcd1ff; 
 
  color:#6040cf; 
 
  font-size:8px; 
 
  font-weight:800; 
 
} 
 
 
.skill-tag:nth-child(4n+2) { 
 
  background:#e2f4f2; 
 
  color:#197777; 
 
  border-color:#c2e3e0; 
 
} 
 
 
.skill-tag:nth-child(4n+3) { 
 
  background:#fff1e2; 
 
  color:#af641d; 
 
  border-color:#eed5b9; 
 
} 
 
 
.skill-tag:nth-child(4n+4) { 
 
  background:#fde9ef; 
 
  color:#ad4364; 
 
  border-color:#efccd8; 
 
} 
 
 
.skill-empty { 
 
  color:#9aa4b0; 
 
  font-size:9px; 
 
} 
 
 
/* ========================================================= 
   APPLICATION STRIP 
   ========================================================= */ 
 
.opportunity-application-strip { 
 
  display:grid; 
 
  grid-template-columns: 
    1.5fr 
    .75fr 
    .75fr 
    .75fr 
    auto; 
 
  align-items:center; 
 
  gap:13px; 
 
  margin-top:14px; 
 
  padding: 
    12px 
    0; 
 
  border-top:1px solid #e7ecf1; 
 
} 
 
 
.application-total span, 
.application-stat span { 
 
  display:block; 
 
  color:#8793a4; 
 
  font-size:7px; 
 
  font-weight:950; 
 
  letter-spacing:.8px; 
 
} 
 
 
.application-total strong { 
 
  display:block; 
 
  margin-top:3px; 
 
  color:#6540d6; 
 
  font-size:19px; 
 
  font-weight:950; 
 
} 
 
 
.application-stat strong { 
 
  display:block; 
 
  margin-top:3px; 
 
  color:#34475c; 
 
  font-size:13px; 
 
  font-weight:850; 
 
} 
 
 
.opportunity-view-btn { 
 
  height:37px; 
 
  padding: 
    0 
    13px; 
 
  display:inline-flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  gap:7px; 
 
  border:0; 
 
  border-radius:8px; 
 
  background: 
    linear-gradient( 
      135deg, 
      #6743df, 
      #7d5ceb 
    ); 
 
  color:#ffffff; 
 
  font-size:9px; 
 
  font-weight:900; 
 
  cursor:pointer; 
 
} 
 
 
.opportunity-view-btn:hover { 
 
  background: 
    linear-gradient( 
      135deg, 
      #5732cd, 
      #6c49dc 
    ); 
 
} 
 
 
/* ========================================================= 
   EMPTY 
   ========================================================= */ 
 
.opportunity-empty { 
 
  padding: 
    55px 
    20px; 
 
  text-align:center; 
 
} 
 
 
.opportunity-empty-icon { 
 
  width:55px; 
 
  height:55px; 
 
  margin: 
    0 
    auto 
    11px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border-radius:14px; 
 
  background:#e7f5f2; 
 
  border:1px solid #c7e5df; 
 
  color:#187d7d; 
 
  font-size:20px; 
 
} 
 
 
.opportunity-empty h3 { 
 
  margin:0; 
 
  color:#30445a; 
 
  font-size:16px; 
 
  font-weight:900; 
 
} 
 
 
.opportunity-empty p { 
 
  margin: 
    5px 
    0 
    0; 
 
  color:#8693a3; 
 
  font-size:10px; 
 
} 
 
 
/* ========================================================= 
   SELECTED DETAILS 
   ========================================================= */ 
 
.opportunity-details-panel { 
 
  border-top: 
    3px 
    solid 
    #6842df; 
 
} 
 
 
.opportunity-details-header { 
 
  display:flex; 
 
  align-items:flex-start; 
 
  justify-content:space-between; 
 
  gap:15px; 
 
  padding-bottom:15px; 
 
  border-bottom:1px solid #e4e9ef; 
 
} 
 
 
.opportunity-details-header > div > span { 
 
  display:block; 
 
  margin-bottom:5px; 
 
  color:#6742dc; 
 
  font-size:8px; 
 
  font-weight:950; 
 
  letter-spacing:1.5px; 
 
} 
 
 
.opportunity-details-header h2 { 
 
  margin:0; 
 
  color:#182e49; 
 
  font-size:24px; 
 
  line-height:1.15; 
 
  font-weight:950; 
 
} 
 
 
.opportunity-details-header p { 
 
  margin: 
    5px 
    0 
    0; 
 
  color:#788699; 
 
  font-size:10px; 
 
} 
 
 
.opportunity-close-btn { 
 
  width:37px; 
 
  height:37px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border:1px solid #d8e0e8; 
 
  border-radius:8px; 
 
  background:#ffffff; 
 
  color:#68788c; 
 
  cursor:pointer; 
 
} 
 
 
.opportunity-close-btn:hover { 
 
  background:#fff0f4; 
 
  color:#b84367; 
 
  border-color:#ebc6d3; 
 
} 
 
 
/* ========================================================= 
   DETAIL SUMMARY 
   ========================================================= */ 
 
.opportunity-detail-summary { 
 
  display:grid; 
 
  grid-template-columns: 
    repeat(4,1fr); 
 
  gap:9px; 
 
  margin: 
    16px 
    0; 
 
} 
 
 
.opportunity-detail-summary > div { 
 
  min-height:62px; 
 
  padding: 
    11px; 
 
  border:1px solid; 
 
  border-radius:8px; 
 
} 
 
 
.opportunity-detail-summary span { 
 
  display:block; 
 
  margin-bottom:4px; 
 
  font-size:7px; 
 
  font-weight:950; 
 
  letter-spacing:.9px; 
 
} 
 
 
.opportunity-detail-summary strong { 
 
  color:#34475b; 
 
  font-size:10px; 
 
  font-weight:850; 
 
} 
 
 
.summary-purple { 
 
  background:#f8f4ff; 
 
  border-color:#e0d7fa; 
 
} 
 
 
.summary-purple span { 
 
  color:#6541d9; 
 
} 
 
 
.summary-purple strong { 
 
  color:#5235b8; 
 
} 
 
 
.summary-teal { 
 
  background:#f1fbfa; 
 
  border-color:#cee9e6; 
 
} 
 
 
.summary-teal span { 
 
  color:#147879; 
 
} 
 
 
.summary-orange { 
 
  background:#fff8ef; 
 
  border-color:#efddc7; 
 
} 
 
 
.summary-orange span { 
 
  color:#b96b20; 
 
} 
 
 
.summary-green { 
 
  background:#f1faf4; 
 
  border-color:#cfe8d8; 
 
} 
 
 
.summary-green span { 
 
  color:#34734f; 
 
} 
 
 
/* ========================================================= 
   DETAIL SECTIONS 
   ========================================================= */ 
 
.opportunity-info-section { 
 
  margin-top:13px; 
 
  padding: 
    17px; 
 
  border:1px solid #dfe6ed; 
 
  border-radius:10px; 
 
  background:#ffffff; 
 
} 
 
 
.company-section { 
 
  border-left: 
    3px 
    solid 
    #6842df; 
 
} 
 
 
.eligibility-section { 
 
  border-left: 
    3px 
    solid 
    #208f90; 
 
} 
 
 
.description-section { 
 
  border-left: 
    3px 
    solid 
    #dc7b29; 
 
} 
 
 
.applications-section { 
 
  border-left: 
    3px 
    solid 
    #ce537c; 
 
} 
 
 
.outcome-section { 
 
  border-left: 
    3px 
    solid 
    #2d9063; 
 
} 
 
 
.opportunity-info-heading { 
 
  display:flex; 
 
  align-items:center; 
 
  gap:9px; 
 
  margin-bottom:13px; 
 
} 
 
 
.info-heading-icon { 
 
  width:35px; 
 
  height:35px; 
 
  flex:0 0 35px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border-radius:8px; 
 
  font-size:13px; 
 
} 
 
 
.info-heading-icon.purple { 
 
  background:#eee7ff; 
 
  color:#6440d9; 
 
} 
 
 
.info-heading-icon.teal { 
 
  background:#e0f4f2; 
 
  color:#197b7c; 
 
} 
 
 
.info-heading-icon.orange { 
 
  background:#fff0e1; 
 
  color:#bc681f; 
 
} 
 
 
.info-heading-icon.pink { 
 
  background:#fde7ee; 
 
  color:#b54369; 
 
} 
 
 
.info-heading-icon.green { 
 
  background:#e2f4e9; 
 
  color:#2d7c54; 
 
} 
 
 
.opportunity-info-heading h3 { 
 
  margin:0; 
 
  color:#30435a; 
 
  font-size:14px; 
 
  font-weight:900; 
 
} 
 
 
.opportunity-info-heading p { 
 
  margin: 
    3px 
    0 
    0; 
 
  color:#7d8999; 
 
  font-size:9px; 
 
} 
 
 
/* ========================================================= 
   INFORMATION GRID 
   ========================================================= */ 
 
.company-info-grid { 
 
  display:grid; 
 
  grid-template-columns: 
    repeat( 
      3, 
      minmax(0,1fr) 
    ); 
 
  gap:9px; 
 
} 
 
 
.company-info-grid > div { 
 
  min-height:57px; 
 
  padding: 
    10px; 
 
  background:#fafbfd; 
 
  border:1px solid #e3e8ee; 
 
  border-radius:8px; 
 
} 
 
 
.company-info-grid span { 
 
  display:block; 
 
  margin-bottom:4px; 
 
  color:#8793a3; 
 
  font-size:7px; 
 
  font-weight:950; 
 
  letter-spacing:.8px; 
 
} 
 
 
.company-info-grid strong { 
 
  color:#31445a; 
 
  font-size:10px; 
 
  line-height:1.35; 
 
  font-weight:800; 
 
} 
 
 
/* ========================================================= 
   DESCRIPTION 
   ========================================================= */ 
 
.job-description-box { 
 
  padding: 
    13px; 
 
  border: 
    1px 
    solid 
    #f0dec8; 
 
  border-radius:8px; 
 
  background: 
    linear-gradient( 
      110deg, 
      #fffaf3, 
      #fffefd 
    ); 
 
  color:#596a7e; 
 
  font-size:10px; 
 
  line-height:1.65; 
 
} 
 
 
/* ========================================================= 
   APPLICATION EMPTY 
   ========================================================= */ 
 
.application-empty { 
 
  min-height:80px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  gap:7px; 
 
  border: 
    1px dashed 
    #d7dfe7; 
 
  border-radius:8px; 
 
  background:#fafbfd; 
 
  color:#8a96a5; 
 
  font-size:9px; 
 
} 
 
 
.application-empty i { 
 
  color:#ce537c; 
 
} 
 
 
/* ========================================================= 
   APPLICATION TABLE 
   ========================================================= */ 
 
.student-application-table, 
.outcome-table { 
 
  width:100%; 
 
  overflow-x:auto; 
 
} 
 
 
.application-table-header, 
.application-table-row { 
 
  min-width:750px; 
 
  display:grid; 
 
  grid-template-columns: 
    1.45fr 
    .9fr 
    .9fr 
    .9fr 
    .9fr; 
 
  align-items:center; 
 
  gap:10px; 
 
} 
 
 
.application-table-header { 
 
  padding: 
    9px 
    11px; 
 
  border-radius: 
    8px 
    8px 
    0 
    0; 
 
  background: 
    linear-gradient( 
      90deg, 
      #eee8ff, 
      #e9f6f4 
    ); 
 
  color:#6242cc; 
 
  font-size:7px; 
 
  font-weight:950; 
 
  letter-spacing:.8px; 
 
} 
 
 
.application-table-row { 
 
  min-height:53px; 
 
  padding: 
    9px 
    11px; 
 
  color:#53647a; 
 
  font-size:9px; 
 
  border: 
    1px 
    solid 
    #e3e8ee; 
 
  border-top:0; 
 
} 
 
 
.student-cell { 
 
  display:flex; 
 
  align-items:center; 
 
  gap:7px; 
 
} 
 
 
.student-avatar { 
 
  width:32px; 
 
  height:32px; 
 
  min-width:32px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border-radius:7px; 
 
  background:#fde9ef; 
 
  color:#ad4566; 
 
  font-size:8px; 
 
  font-weight:900; 
 
} 
 
 
.student-cell strong { 
 
  display:block; 
 
  color:#30435a; 
 
  font-size:9px; 
 
  font-weight:850; 
 
} 
 
 
.student-cell small { 
 
  display:block; 
 
  margin-top:2px; 
 
  color:#8490a1; 
 
  font-size:7px; 
 
} 
 
 
.table-status { 
 
  display:inline-block; 
 
  padding: 
    5px 
    7px; 
 
  border-radius:5px; 
 
  font-size:7px; 
 
  font-weight:850; 
 
} 
 
 
.application-status { 
 
  background:#eee8ff; 
 
  color:#6140ce; 
 
  border:1px solid #ddd1ff; 
 
} 
 
 
.offer-status { 
 
  background:#fff1df; 
 
  color:#ab631e; 
 
  border:1px solid #edd3b3; 
 
} 
 
 
.interview-status { 
 
  background:#e2f4f2; 
 
  color:#177878; 
 
  border:1px solid #c3e3e1; 
 
} 
 
 
.table-date { 
 
  color:#5b6c80; 
 
  font-size:9px; 
 
} 
 
 
/* ========================================================= 
   OUTCOME TABLE 
   ========================================================= */ 
 
.outcome-table-header, 
.outcome-table-row { 
 
  min-width:750px; 
 
  display:grid; 
 
  grid-template-columns: 
    1.45fr 
    1fr 
    1fr 
    .8fr 
    1fr; 
 
  align-items:center; 
 
  gap:10px; 
 
} 
 
 
.outcome-table-header { 
 
  padding: 
    9px 
    11px; 
 
  background: 
    linear-gradient( 
      90deg, 
      #e6f5eb, 
      #f0faf5 
    ); 
 
  color:#2f7954; 
 
  border-radius: 
    8px 
    8px 
    0 
    0; 
 
  font-size:7px; 
 
  font-weight:950; 
 
  letter-spacing:.8px; 
 
} 
 
 
.outcome-table-row { 
 
  min-height:53px; 
 
  padding: 
    9px 
    11px; 
 
  border: 
    1px 
    solid 
    #e0ebe4; 
 
  border-top:0; 
 
  color:#506478; 
 
  font-size:9px; 
 
} 
 
 
.outcome-table-row strong { 
 
  display:block; 
 
  color:#30495a; 
 
  font-size:9px; 
 
  font-weight:850; 
 
} 
 
 
.outcome-table-row small { 
 
  display:block; 
 
  margin-top:2px; 
 
  color:#86929f; 
 
  font-size:7px; 
 
} 
 
 
.verification-status { 
 
  display:inline-block; 
 
  padding: 
    5px 
    7px; 
 
  border-radius:5px; 
 
  background:#e4f5eb; 
 
  border:1px solid #c4e2d1; 
 
  color:#2b7450; 
 
  font-size:7px; 
 
  font-weight:850; 
 
} 
 
 
/* ========================================================= 
   READ ONLY 
   ========================================================= */ 
 
.read-only-banner { 
 
  margin-top:14px; 
 
  padding: 
    12px; 
 
  display:flex; 
 
  align-items:flex-start; 
 
  gap:9px; 
 
  background: 
    linear-gradient( 
      100deg, 
      #edf8f7, 
      #f4fbff 
    ); 
 
  border: 
    1px 
    solid 
    #cbe2e0; 
 
  border-radius:8px; 
 
} 
 
 
.read-only-icon { 
 
  width:31px; 
 
  height:31px; 
 
  min-width:31px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  border-radius:7px; 
 
  background:#dff3f0; 
 
  color:#19797c; 
 
} 
 
 
.read-only-banner strong { 
 
  display:block; 
 
  color:#315d66; 
 
  font-size:9px; 
 
  font-weight:900; 
 
} 
 
 
.read-only-banner p { 
 
  margin: 
    3px 
    0 
    0; 
 
  color:#6f8191; 
 
  font-size:8px; 
 
  line-height:1.5; 
 
} 
 
 
/* ========================================================= 
   FOOTER 
   ========================================================= */ 
 
.trainer-dashboard-footer { 
 
  width:100%; 
 
  padding: 
    14px 
    2px 
    3px; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:space-between; 
 
  color:#8491a1; 
 
  font-size:8px; 
 
  font-weight:700; 
 
} 
 
 
/* ========================================================= 
   LOADING 
   ========================================================= */ 
 
.trainer-dashboard-loading { 
 
  position:fixed; 
 
  inset:0; 
 
  z-index:2147483647; 
 
  display:flex; 
 
  align-items:center; 
 
  justify-content:center; 
 
  gap:9px; 
 
  background:#f3f6fb; 
 
  color:#738297; 
 
  font-size:11px; 
 
} 
 
 
.trainer-dashboard-loading i { 
 
  color:#6641db; 
 
  font-size:17px; 
 
} 
 
 
/* ========================================================= 
   1200px 
   ========================================================= */ 
 
@media (max-width:1200px){ 
 
  .campus360-opportunities-app 
  .campus360-trainer-sidebar { 
 
    width:260px !important; 
 
    min-width:260px !important; 
 
    max-width:260px !important; 
 
    flex-basis:260px !important; 
 
    background: 
      linear-gradient( 
        180deg, 
        #130d2f 0%, 
        #160d38 48%, 
        #100a29 100% 
      ) !important; 
 
    border-right:1px solid #2d2157 !important; 
 
  } 
 
 
  .campus360-trainer-main { 
 
    width: 
      calc(100vw - 260px) !important; 
 
    max-width: 
      calc(100vw - 260px) !important; 
 
  } 
 
 
  .opportunity-kpi-grid { 
 
    grid-template-columns: 
      repeat(2,minmax(0,1fr)); 
 
  } 
 
 
  .opportunity-details-grid { 
 
    grid-template-columns: 
      repeat(2,minmax(0,1fr)); 
 
  } 
 
 
  .company-info-grid { 
 
    grid-template-columns: 
      repeat(2,minmax(0,1fr)); 
 
  } 
 
 
  .opportunity-detail-summary { 
 
    grid-template-columns: 
      repeat(2,minmax(0,1fr)); 
 
  } 
 
} 
 
 
/* ========================================================= 
   950px 
   ========================================================= */ 
 
@media (max-width:950px){ 
 
  .campus360-opportunities-app 
  .campus360-trainer-sidebar { 
 
    position:fixed !important; 
 
    top:0 !important; 
 
    left:0 !important; 
 
    bottom:0 !important; 
 
    width:280px !important; 
 
    min-width:280px !important; 
 
    max-width:280px !important; 
 
    flex-basis:280px !important; 
 
    height:100vh !important; 
 
    transform:translateX(-100%); 
 
    background: 
      linear-gradient( 
        180deg, 
        #130d2f 0%, 
        #160d38 48%, 
        #100a29 100% 
      ) !important; 
 
    border-right:1px solid #2d2157 !important; 
 
    box-shadow: 
      8px 
      0 
      30px 
      rgba(10,7,30,.30); 
 
  } 
 
 
  .campus360-opportunities-app 
  .campus360-trainer-sidebar { 
 
    transform:translateX(-100%); 
 
  } 
 
 
  .campus360-opportunities-app:not(.sidebar-collapsed) 
  .campus360-trainer-sidebar { 
 
    transform:translateX(0); 
 
  } 
 
 
  .campus360-trainer-main { 
 
    width:100% !important; 
 
    max-width:100% !important; 
 
  } 
 
 
  .trainer-sidebar-overlay { 
 
    position:fixed; 
 
    inset:0; 
 
    z-index:1900; 
 
    display:block; 
 
    background: 
      rgba(22,34,52,.34); 
 
  } 
 
 
  .sidebar-collapsed 
  .trainer-sidebar-overlay { 
 
    display:none; 
 
  } 
 
 
  .opportunity-welcome { 
 
    flex-direction:column; 
 
    align-items:flex-start; 
 
  } 
 
 
  .opportunity-trainer-card { 
 
    width:100%; 
 
    min-width:0; 
 
  } 
 
 
  .opportunity-search-grid { 
 
    grid-template-columns:1fr; 
 
  } 
 
 
  .opportunity-card-top { 
 
    grid-template-columns: 
      auto 
      minmax(0,1fr); 
 
  } 
 
 
  .opportunity-status-wrapper { 
 
    grid-column:2; 
 
  } 
 
 
  .opportunity-application-strip { 
 
    grid-template-columns: 
      repeat(3,minmax(0,1fr)); 
 
  } 
 
 
  .opportunity-view-btn { 
 
    grid-column:1/-1; 
 
    width:100%; 
 
  } 
 
} 
 
 
/* ========================================================= 
   700px 
   ========================================================= */ 
 
