    linear-gradient( 
      180deg, 
      #130d2f 0%, 
      #160d38 48%, 
      #100a29 100% 
    ) !important; 
 
  border-right:1px solid #2d2157 !important; 
 
} 
 
 
.campus360-opportunities-app 
