.trainer-brand { 
 
  background: 
    linear-gradient( 
      135deg, 
      #170e38, 
      #1c1045 
    ) !important; 
 
  border-bottom:1px solid #2d2157 !important; 
 
} 
 
 
.campus360-opportunities-app 
.campus360-trainer-sidebar 
.trainer-profile-mini { 
 
  background: 
    linear-gradient( 
      135deg, 
      #211342, 
      #29164f 
    ) !important; 
 
  border-color:#4b3475 !important; 
 
} 
 
 
.campus360-opportunities-app 
