  color:#ffffff !important; 
 
} 
 
 
/* ========================================================= 
   END 
   ========================================================= */

sp_widget.script:
(function() {

    /* ============================================================
       CAMPUS360 TRAINER OPPORTUNITIES

       READ ONLY

       Tables:
       1. x_snc_campus360_placement_opportunity
       2. x_snc_campus360_student_application
       3. x_snc_campus360_placement_outcome
       4. x_snc_campus360_company_master
       ============================================================ */


    data.loaded = false;


    /* ============================================================
       HELPER FUNCTIONS
       ============================================================ */

    function safeValue(
        gr,
        field
    ) {

        if (
            !gr ||
            !gr.isValidField(field)
        ) {

            return '';

        }

        return (
            gr.getDisplayValue(field) ||
            gr.getValue(field) ||
            ''
        );

    }


    function rawValue(
        gr,
        field
    ) {

        if (
            !gr ||
            !gr.isValidField(field)
        ) {

            return '';

        }

        return (
            gr.getValue(field) ||
            ''
        );

    }


    function getInitials(
        name
    ) {

        name =
            (name || '')
                .toString()
                .trim();


        if (!name) {
            return 'OP';
        }


        var parts =
            name.split(/\s+/);


        if (
            parts.length === 1
        ) {

            return parts[0]
                .substring(0, 2)
                .toUpperCase();

        }


        return (
            parts[0].charAt(0) +
            parts[parts.length - 1].charAt(0)
        ).toUpperCase();

    }


    function formatDate(
        value
    ) {

        if (!value) {
            return '';
        }


        try {

            var gdt =
                new GlideDateTime(value);

            return gdt
                .getDate()
                .getDisplayValue();

        } catch (e) {

            return value;

        }

    }


    function normalizeStatus(
        value
    ) {

        if (!value) {
            return '';
        }


        return value
            .toString()
            .trim();

    }


    /* ============================================================
       CURRENT TRAINER
       ============================================================ */

    var trainerId =
        '';

    try {

        trainerId =
            (input && input.trainerId) ||
            gs.getSession()
                .getClientData('trainer_id') ||
            '';

    } catch (trainerError) {

        trainerId = '';

    }


    /*
     * The trainer ID is normally supplied in the URL:
     *
     * ?id=campus360_trainer_opportunities&trainer=TR001
     *
     * Server-side gs action parameters are not always directly
     * available from the widget URL, so we also read the request.
     */

    try {

        var request =
            gs.action.getGlideURI();

        if (request) {

            var requestTrainer =
                request.get('trainer');

            if (requestTrainer) {
                trainerId =
                    requestTrainer;
            }

        }

    } catch (uriError) {

        // Keep existing trainerId.

    }


    /* ============================================================
       TRAINER DATA
       ============================================================ */

    data.trainer = {

        id: trainerId || '',

        name: '',

        initials: ''

    };


    if (trainerId) {

        var trainerGR =
            new GlideRecord(
                'x_snc_campus360_trainer_master'
            );


        trainerGR.addQuery(
            'u_trainer_id',
            trainerId
        );


        trainerGR.query();


        if (trainerGR.next()) {

            data.trainer.name =
                safeValue(
                    trainerGR,
                    'u_trainer_name'
                ) ||
                safeValue(
                    trainerGR,
                    'name'
                ) ||
                trainerId;


            data.trainer.initials =
                getInitials(
                    data.trainer.name
                );

        }

    }


    if (!data.trainer.name) {

        data.trainer.name =
            trainerId ||
            'Trainer';

        data.trainer.initials =
            getInitials(
                data.trainer.name
            );

    }


    /* ============================================================
       SUMMARY
       ============================================================ */

    data.summary = {

        total: 0,

        open: 0,

        applications: 0,

        placed: 0

    };


    data.opportunities = [];


    /* ============================================================
       LOAD PLACEMENT OUTCOMES FIRST

       Used for summary count and opportunity details.
       ============================================================ */

    var outcomeMap = {};


    var outcomeGR =
        new GlideRecord(
            'x_snc_campus360_placement_outcome'
        );


    outcomeGR.query();


    while (
        outcomeGR.next()
    ) {

        var outcomeOpportunity =
            rawValue(
                outcomeGR,
                'u_opportunity'
            );


        if (
            !outcomeOpportunity
        ) {

            continue;

        }


        if (
            !outcomeMap[
                outcomeOpportunity
            ]
        ) {

            outcomeMap[
                outcomeOpportunity
            ] = [];

        }


        var outcomeStudent =
            outcomeGR.student;


        var outcomeStudentName =
            '';


        var outcomeStudentId =
            '';


        if (
            outcomeStudent &&
            outcomeStudent.getRefRecord
        ) {

            var outcomeStudentGR =
                outcomeStudent.getRefRecord();


            if (
                outcomeStudentGR &&
                outcomeStudentGR.isValidRecord()
            ) {

                outcomeStudentName =
                    safeValue(
                        outcomeStudentGR,
                        'u_student_name'
                    ) ||
                    safeValue(
                        outcomeStudentGR,
                        'student_name'
                    );


                outcomeStudentId =
                    safeValue(
                        outcomeStudentGR,
                        'u_student_id'
                    ) ||
                    safeValue(
                        outcomeStudentGR,
                        'student_id'
                    );

            }

        }


        outcomeMap[
            outcomeOpportunity
        ].push({

            sys_id:
                outcomeGR.getUniqueValue(),

            student_name:
                outcomeStudentName,

            student_id:
                outcomeStudentId,

            outcome_type:
                safeValue(
                    outcomeGR,
                    'u_outcome_type'
                ) ||
                safeValue(
                    outcomeGR,
                    'outcome_type'
                ),

            joining_date:
                formatDate(
                    rawValue(
                        outcomeGR,
                        'u_joining_date'
                    ) ||
                    rawValue(
                        outcomeGR,
                        'joining_date'
                    )
                ),

            placement_type:
                safeValue(
                    outcomeGR,
                    'u_placement_type'
                ) ||
                safeValue(
                    outcomeGR,
                    'placement_type'
                ),

            ctc:
                safeValue(
                    outcomeGR,
                    'u_ctc'
                ) ||
                safeValue(
                    outcomeGR,
                    'ctc'
                ),

            verification_status:
                safeValue(
                    outcomeGR,
                    'u_verification_status'
                ) ||
                safeValue(
                    outcomeGR,
                    'verification_status'
                ),

            company_name:
                safeValue(
                    outcomeGR,
                    'u_company'
                ) ||
                safeValue(
                    outcomeGR,
                    'company'
                )

        });

    }


    /* ============================================================
       LOAD PLACEMENT OPPORTUNITIES
       ============================================================ */

    var opportunityGR =
        new GlideRecord(
            'x_snc_campus360_placement_opportunity'
        );


    opportunityGR.orderByDesc(
        'sys_created_on'
    );


    opportunityGR.query();


    while (
        opportunityGR.next()
    ) {

        var opportunityId =
            safeValue(
                opportunityGR,
                'u_opportunity_id'
            ) ||
            safeValue(
                opportunityGR,
                'opportunity_id'
            );


        var opportunityTitle =
            safeValue(
                opportunityGR,
                'u_opportunity_title'
            ) ||
            safeValue(
                opportunityGR,
                'opportunity_title'
            );


        var opportunityStatus =
            normalizeStatus(
                safeValue(
                    opportunityGR,
                    'u_status'
                ) ||
                safeValue(
                    opportunityGR,
                    'status'
                )
            );


        var opportunityType =
            safeValue(
                opportunityGR,
                'u_opportunity_type'
            ) ||
            safeValue(
                opportunityGR,
                'opportunity_type'
            );


        var companyName =
            '';


        var companyId =
            '';


        var companyType =
            '';


        var industry =
            '';


        var recruiterName =
            '';


        var recruiterEmail =
            '';


        /*
         * Company is a reference to Company Master.
         */

        if (
            opportunityGR.company &&
            opportunityGR.company.getRefRecord
        ) {

            var companyGR =
                opportunityGR.company.getRefRecord();


            if (
                companyGR &&
                companyGR.isValidRecord()
            ) {

                companyName =
                    safeValue(
                        companyGR,
                        'u_company_name'
                    ) ||
                    safeValue(
                        companyGR,
                        'company_name'
                    );


                companyId =
                    safeValue(
                        companyGR,
                        'u_company_id'
                    ) ||
                    safeValue(
                        companyGR,
                        'company_id'
                    );


                companyType =
                    safeValue(
                        companyGR,
                        'u_company_type'
                    ) ||
                    safeValue(
                        companyGR,
                        'company_type'
                    );


                industry =
                    safeValue(
                        companyGR,
                        'u_industry'
                    ) ||
                    safeValue(
                        companyGR,
                        'industry'
                    );


                recruiterName =
                    safeValue(
                        companyGR,
                        'u_recruiter_name'
                    ) ||
                    safeValue(
                        companyGR,
                        'recruiter_name'
                    );


                recruiterEmail =
                    safeValue(
                        companyGR,
                        'u_recruiter_email'
                    ) ||
                    safeValue(
                        companyGR,
                        'recruiter_email'
                    );

            }

        }


        /*
         * Fallback to display value if the reference
         * could not be expanded.
         */

        if (!companyName) {

            companyName =
                safeValue(
                    opportunityGR,
                    'u_company'
                ) ||
                safeValue(
                    opportunityGR,
                    'company'
                );

        }


        var opportunity = {

            sys_id:
                opportunityGR.getUniqueValue(),

            opportunity_id:
                opportunityId,

            title:
                opportunityTitle,

            status:
                opportunityStatus,

            opportunity_type:
                opportunityType,

            opportunity_source:
                safeValue(
                    opportunityGR,
                    'u_opportunity_source'
                ) ||
                safeValue(
                    opportunityGR,
                    'opportunity_source'
                ),

            company_name:
                companyName,

            company_id:
                companyId,

            company_type:
                companyType,

            industry:
                industry,

            recruiter_name:
                recruiterName,

            recruiter_email:
                recruiterEmail,

            location:
                safeValue(
                    opportunityGR,
                    'u_location'
                ) ||
                safeValue(
                    opportunityGR,
                    'location'
                ),

            job_description:
                safeValue(
                    opportunityGR,
                    'u_job_description'
                ) ||
                safeValue(
                    opportunityGR,
                    'job_description'
                ),

            required_skills:
                safeValue(
                    opportunityGR,
                    'u_required_skills'
                ) ||
                safeValue(
                    opportunityGR,
                    'required_skills'
                ),

            eligible_branches:
                safeValue(
                    opportunityGR,
                    'u_eligible_branches'
                ) ||
                safeValue(
                    opportunityGR,
                    'eligible_branches'
                ),

            minimum_cgpa:
                safeValue(
                    opportunityGR,
                    'u_minimum_cgpa'
                ) ||
                safeValue(
                    opportunityGR,
                    'minimum_cgpa'
                ),

            ctc_stipend:
                safeValue(
                    opportunityGR,
                    'u_ctc_stipend'
                ) ||
                safeValue(
                    opportunityGR,
                    'ctc_stipend'
                ),

            application_deadline:
                formatDate(
                    rawValue(
                        opportunityGR,
                        'u_application_deadline'
                    ) ||
                    rawValue(
                        opportunityGR,
                        'application_deadline'
                    )
                ),

            drive_date:
                formatDate(
                    rawValue(
                        opportunityGR,
                        'u_drive_date'
                    ) ||
                    rawValue(
                        opportunityGR,
                        'drive_date'
                    )
                ),

            skillList: [],

            application_count: 0,

            pending_count: 0,

            shortlisted_count: 0,

            selected_count: 0,

            applications: [],

            outcomes:
                outcomeMap[
                    opportunityGR.getUniqueValue()
                ] || []

        };


        /* ========================================================
           SKILLS
           ======================================================== */

        var skillText =
            opportunity.required_skills ||
            '';


        if (skillText) {

            opportunity.skillList =
                skillText
                    .split(',')
                    .map(
                        function(skill) {

                            return skill
                                .trim();

                        }
                    )
                    .filter(
                        function(skill) {

                            return !!skill;

                        }
                    );

        }


        /*
         * Company initials
         */

        opportunity.companyInitials =
            getInitials(
                companyName ||
                opportunityTitle ||
                'OP'
            );


        /* ========================================================
           APPLICATIONS FOR THIS OPPORTUNITY
           ======================================================== */

        var applicationGR =
            new GlideRecord(
                'x_snc_campus360_student_application'
            );


        /*
         * Opportunity is a reference field.
         */

        if (
            applicationGR.isValidField(
                'u_opportunity'
            )
        ) {

            applicationGR.addQuery(
                'u_opportunity',
                opportunityGR.getUniqueValue()
            );

        } else if (
            applicationGR.isValidField(
                'opportunity'
            )
        ) {

            applicationGR.addQuery(
                'opportunity',
                opportunityGR.getUniqueValue()
            );

        } else {

            applicationGR =
                null;

        }


        if (applicationGR) {

            applicationGR.query();


            while (
                applicationGR.next()
            ) {

                opportunity.application_count++;


                var applicationStatus =
                    normalizeStatus(
                        safeValue(
                            applicationGR,
                            'u_application_status'
                        ) ||
                        safeValue(
                            applicationGR,
                            'application_status'
                        )
                    );


                var offerStatus =
                    normalizeStatus(
                        safeValue(
                            applicationGR,
                            'u_offer_status'
                        ) ||
                        safeValue(
                            applicationGR,
                            'offer_status'
                        )
                    );


                var interviewStatus =
                    normalizeStatus(
                        safeValue(
                            applicationGR,
                            'u_interview_status'
                        ) ||
                        safeValue(
                            applicationGR,
                            'interview_status'
                        )
                    );


                /*
                 * Summary counters.
                 */

                if (
                    applicationStatus
                        .toLowerCase()
                        .indexOf('short') !== -1
                ) {

                    opportunity.shortlisted_count++;

                }


                if (
                    applicationStatus
                        .toLowerCase()
                        .indexOf('select') !== -1 ||
                    offerStatus
                        .toLowerCase()
                        .indexOf('accept') !== -1
                ) {

                    opportunity.selected_count++;

                }


                if (
                    !applicationStatus ||
                    applicationStatus
                        .toLowerCase()
                        .indexOf('pending') !== -1
                ) {

                    opportunity.pending_count++;

                }


                /* =================================================
                   STUDENT
                   ================================================= */

                var studentName =
                    '';


                var studentId =
                    '';


                if (
                    applicationGR.student &&
                    applicationGR.student.getRefRecord
                ) {

                    var studentGR =
                        applicationGR.student.getRefRecord();


                    if (
                        studentGR &&
                        studentGR.isValidRecord()
                    ) {

                        studentName =
                            safeValue(
                                studentGR,
                                'u_student_name'
                            ) ||
                            safeValue(
                                studentGR,
                                'student_name'
                            );


                        studentId =
                            safeValue(
                                studentGR,
                                'u_student_id'
                            ) ||
                            safeValue(
                                studentGR,
                                'student_id'
                            );

                    }

                }


                if (!studentName) {

                    studentName =
                        safeValue(
                            applicationGR,
                            'u_student'
                        ) ||
                        safeValue(
                            applicationGR,
                            'student'
                        );

                }


                if (!studentId) {

                    studentId =
                        safeValue(
                            applicationGR,
                            'u_student_id'
                        ) ||
                        safeValue(
                            applicationGR,
                            'student_id'
                        );

                }


                opportunity.applications.push({

                    sys_id:
                        applicationGR.getUniqueValue(),

                    student_name:
                        studentName,

                    student_id:
                        studentId,

                    initials:
                        getInitials(
                            studentName
                        ),

                    application_status:
                        applicationStatus,

                    assessment_status:
                        safeValue(
                            applicationGR,
                            'u_assessment_status'
                        ) ||
                        safeValue(
                            applicationGR,
                            'assessment_status'
                        ),

                    offer_status:
                        offerStatus,

                    student_response:
                        safeValue(
                            applicationGR,
                            'u_student_response'
                        ) ||
                        safeValue(
                            applicationGR,
                            'student_response'
                        ),

                    applied_date:
                        formatDate(
                            rawValue(
                                applicationGR,
                                'u_applied_date'
                            ) ||
                            rawValue(
                                applicationGR,
                                'applied_date'
                            )
                        ),

                    interview_status:
                        interviewStatus,

                    shortlisted:
                        safeValue(
                            applicationGR,
                            'u_shortlisted'
                        ) ||
                        safeValue(
                            applicationGR,
                            'shortlisted'
                        )

                });

            }

        }


        /* ========================================================
           SUMMARY
           ======================================================== */

        data.summary.total++;


        if (
            opportunityStatus
                .toLowerCase() ===
            'open'
        ) {

            data.summary.open++;

        }


        data.summary.applications +=
            opportunity.application_count;


        data.summary.placed +=
            opportunity.outcomes.length;


        data.opportunities.push(
            opportunity
        );

    }


    /* ============================================================
       DATA LIMIT

       Keep the widget responsive for larger datasets.
       ============================================================ */

    if (
        data.opportunities.length > 100
    ) {

        data.opportunities =
            data.opportunities.slice(
                0,
                100
            );

    }


    /* ============================================================
       FINAL STATE
       ============================================================ */

    data.loaded = true;


})();

data.aiWidget = $sp.getWidget('campus360_ai_assistant');
